                }
                Err(e) => {
                    eprintln!("tetel: {e}");
                    ExitCode::from(1)
                }
            }
        }
        Command::Render { out } => {
            let workspace_dir = tetel::workspace::workspace_dir(&cli.workspace);
            let rendered = match tetel::compose::render(&workspace_dir) {
                Ok(r) => r,
