//! Renders the output contract: exactly two labelled partitions, each
//! stating its own scope on the same line, no standalone document-level
//! verdict anywhere. See the crate README / design memo for the contract
//! this implements.

use crate::checks::Findings;
use crate::parse::Document;
use crate::snapshot::Provenance;

/// Exit codes. 0 and 1 are the conventional pass/fail; 2 is the D8 state —
/// "no tetel rows found" — which must never be confusable with clean.
pub const EXIT_CLEAN: i32 = 0;
pub const EXIT_CHECK_FAILED: i32 = 1;
pub const EXIT_NO_ROWS: i32 = 2;

const NON_COVERAGE: &[&str] = &[
    "dependents that never declared themselves",
    "deleted premises",
    "one word used in two senses",
    "a command that runs green without establishing its proposition",
    "unfalsifiable-shaped claim phrasing",
];

/// `build` names the binary that produced this report (see `buildid.rs`).
/// It is passed in rather than read here so this function stays a pure
/// function of the document it grades — and it is *always* printed,
/// including on the no-rows path, because the whole point is that two
/// outputs which disagree can be told apart by their checker. A report
/// that does not name its build cannot be disbelieved.
pub fn render(display_path: &str, doc: &Document, findings: &Findings, build: &str) -> (i32, String) {
    if doc.row_groups_found == 0 && findings.ledger_claims_found == 0 {
        let msg = format!(
            "no tetel rows found in {display_path} — out of scope, nothing was checked. \
This is a distinct state from a clean run, not a weaker way of spelling it (exit {EXIT_NO_ROWS}).\n\
\nchecked by {build}\n"
        );
        return (EXIT_NO_ROWS, msg);
    }

    let mut out = String::new();

    // --- machine-checked partition -----------------------------------
    let failing = findings.machine_check_failed();
    let total_failures = findings.grammar_errors.len()
        + findings.subset_failures.len()
        + findings.abutting_failures.len()
        + findings.unsettled_failures.len()
        + findings.cascade_failures.len()
        + findings.ledger_errors.len()
        + findings.verdict_disagreements.len()
        + findings.out_of_proof.len()
        + usize::from(findings.provenance_failed());
    let scope = "grammar, subset (enumerated rows only), abutting literals, unsettled citations, \
dependency cascades, evidence-ledger import, verdict disagreement, claims out of proof, provenance drift";
    if failing {
        out.push_str(&format!(
            "machine-checked: {total_failures} failing — {scope}\n"
        ));
        for e in &findings.grammar_errors {
            out.push_str(&format!("  - [grammar] {e}\n"));
        }
        for e in &findings.subset_failures {
            out.push_str(&format!("  - [subset] {e}\n"));
        }
        for e in &findings.abutting_failures {
            out.push_str(&format!("  - [abutting-literal] {e}\n"));
        }
        for e in &findings.unsettled_failures {
            out.push_str(&format!("  - [unsettled-citation] {e}\n"));
        }
        for e in &findings.cascade_failures {
            out.push_str(&format!("  - [cascade] {e}\n"));
        }
        for e in &findings.ledger_errors {
            out.push_str(&format!("  - [ledger] {e}\n"));
        }
        for e in &findings.verdict_disagreements {
            out.push_str(&format!("  - [verdict-disagreement] {e}\n"));
        }
        for e in &findings.out_of_proof {
            out.push_str(&format!("  - [out-of-proof] {e}\n"));
        }
        match &findings.provenance {
            Provenance::Drifted { first_diff_line, snapshot_lines, memo_lines } => {
                let where_ = match first_diff_line {
                    Some(n) => format!("first difference at line {n}"),
                    None => "identical line-for-line but different lengths".to_string(),
                };
                out.push_str(&format!(
                    "  - [provenance-drift] this document is not what its own snapshot renders \
({where_}; snapshot {snapshot_lines} lines, document {memo_lines}). Either the document was \
edited by hand after rendering, or the workspace moved on without a re-render — a reader \
following a citation would land somewhere this text was never produced from. Re-render, or \
recover the workspace the text really came from.\n"
                ));
            }
            Provenance::Unreadable(e) => {
                out.push_str(&format!(
                    "  - [provenance-drift] a snapshot exists beside this document but could not \
be rendered from ({e}) — reported rather than passed over, because an unreadable record is not \
a matching one.\n"
                ));
            }
            Provenance::Missing | Provenance::Matches => {}
        }
    } else {
        out.push_str(&format!("machine-checked: clean — {scope}\n"));
    }
    if !findings.abutting_candidates.is_empty() {
        out.push_str("  informational, not checked (never a failure, at any distance looser than abutting):\n");
        for c in &findings.abutting_candidates {
            out.push_str(&format!("    - {c}\n"));
        }
    }

    out.push('\n');

    // --- human-owed partition -----------------------------------------
    out.push_str(
        "human-owed: every READING/OBSERVED/ATTESTED row, every row whose domain or extent \
contains a proc:/external designator, the working-tree states this memo's facts were taken \
against, the RUN command\u{2194}proposition correspondence, \
cited-but-undefined and defined-but-uncited ids, ungrounded ledger claims, claims grounded only \
by attested (ingested) evidence, evidence sources that do not resolve, ledger claims with no \
declared scope at all, qualified verdicts, superseded evidence, facts whose note names a location outside their own \
 captured extent, refusals recorded in a fact's own mint window, \
and tetel's own standing non-coverage \u{2014} none of this is settled by a passing check\n",
    );
    for e in &findings.superseded_evidence {
        out.push_str(&format!("  - superseded evidence: {e}\n"));
//! Runs the five reddening checks plus the report-only observations
//! (cited-but-undefined, defined-but-uncited) against a parsed [`Document`].
//!
//! Check 5 (the dependency-propagation cascade) shares its citation
//! syntax with check 4 but not its scope: check 4 owns direct, hop-1
//! prose citations of an unsettled row. Check 5 owns everything check 4
//! cannot see — row→row citation edges (found inside a row's own
//! `claim`/`note` fields, at any hop, including hop 1) and any citation,
//! prose or row, reached transitively at hop ≥ 2. Between them every
//! citation of an unsettled row is caught exactly once.

use std::collections::{HashMap, HashSet, VecDeque};
use std::path::Path;

use crate::citations::{
    abutting_context, citation_ids_in, normalize_literal, scan_citations, AbuttingContext, Citation,
};
use crate::evidence::{EvidenceRecord, Source, Verdict};
use crate::ledger::Claim;
use crate::model::{Designator, Kind, Row, Status};
use crate::parse::Document;

/// Everything the report needs, already computed. Kept as plain owned
/// data (not references into `Document`) so it's simple to assert on in
/// tests and simple to render.
pub struct Findings {
    /// Formatted `line N: message`, sorted by line — check 1.
    pub grammar_errors: Vec<String>,
    /// Formatted failures — check 2, enumerated rows only.
    pub subset_failures: Vec<String>,
    /// Rows check 2 could not run on at all: `(id, claim)`.
    pub coverage_skipped: Vec<(String, String)>,
    /// Formatted failures — check 3.
    pub abutting_failures: Vec<String>,
    /// Formatted informational near-misses for check 3 (never fail).
    pub abutting_candidates: Vec<String>,
    /// Formatted failures — check 4.
    pub unsettled_failures: Vec<String>,
    /// Formatted failures — check 5. One entry per unsettled root that
    /// has at least one qualifying dependent, each entry a multi-line
    /// block naming every dependent under that root (grouped, not one
    /// finding per dependent — see the module doc comment).
    pub cascade_failures: Vec<String>,
    /// IDs cited in prose with no matching row.
    pub cited_undefined: Vec<String>,
    /// Rows never cited anywhere: `(id, claim)`.
    pub defined_uncited: Vec<(String, String)>,
    /// READING/OBSERVED/ATTESTED rows: `(id, "KIND/STATUS", claim)`.
    pub human_owed_rows: Vec<(String, String, String)>,
    /// IDs of every RUN row, for the class-level correspondence line.
    pub run_row_ids: Vec<String>,

    // --- the grounding brief/record/check slice ---------------------
    /// How many claims the memo's evidence ledger table(s) carried, valid
    /// or not — distinguishes "no ledger in this file" from "a ledger
    /// with zero rows" for the report's early-exit guard.
    pub ledger_claims_found: usize,
    /// Formatted `line N: message` — ledger rows that could not be
    /// parsed at all (wrong cell count, empty id, duplicate id). Never
    /// silently dropped.
    pub ledger_errors: Vec<String>,
    /// A ledger claim with no evidence record at all: `(id, proposition)`.
    /// Human-owed — absence of evidence is not itself a failure.
    pub ungrounded_claims: Vec<(String, String)>,
    /// A ledger claim grounded, but only by evidence that derives to
    /// [`Kind::Attested`] for standing — today, that's *every* grounded
    /// claim, since ingestion (`tetel record`) is the only write path and
    /// every ingested record derives to `Attested` regardless of what it
    /// claims (see `evidence::EvidenceRecord::derived_kind`). Distinct
    /// from `ungrounded_claims`: this is "someone looked, off-instrument",
    /// not "nobody looked". `(id, proposition)`, human-owed, never a
    /// failure — it stops being the whole list only once a witnessed
    /// grounding exists to sit beside ingested ones.
    pub attested_grounded_claims: Vec<(String, String)>,
    /// One line per evidence record whose `source` is a path that does not
    /// resolve on disk. Human-owed, never a failure — mirrors the
    /// non-failing disposition of `cited_undefined`, one line per record
    /// (not aggregated into a bracketed list) since each names a distinct
    /// claim and path.
    pub unresolved_evidence_sources: Vec<String>,
    /// A ledger claim whose Domain/Extent cells are exactly
    /// [`crate::ledger::NO_SCOPE_DECLARED`] — minted by `tetel claim` via
    /// `compose::render`, which has no scope field to draw from.
    /// Human-owed, never a failure: distinct from `coverage_skipped`
    /// (a *declared* domain/extent this crate's checks can't enumerate,
    /// e.g. a `proc:`/`external:` designator) — this is a domain/extent
    /// that was never declared at all, and it says so plainly rather than
    /// let a silently-passing check imply a coverage claim nobody made.
    pub no_scope_claims: Vec<(String, String)>,
    /// Formatted failures: two evidence records for one claim disagreeing
    /// on verdict, or a verdict contradicting the author's own Status
    /// cell. A machine failure — an unresolved contradiction, the same
    /// shape as the unsettled-citation check.
    pub verdict_disagreements: Vec<String>,
    /// Whether the memo still matches the workspace snapshot beside it.
    /// See [`crate::snapshot`] for why a rendered document is not
    /// self-contained and what a mismatch means.
    pub provenance: crate::snapshot::Provenance,
    /// Whether the memo cites anything at all. A document with no
    /// citations owes no snapshot, so a missing one is only worth
    /// reporting when something in the text points into a workspace.
    pub cites_something: bool,
    /// Facts whose note names a location their own captured extent does
    /// not cover. Human-owed: see [`crate::scope`] for why this is a
    /// scope check rather than a truth check, and why it never refuses.
    /// Only populated when a snapshot shipped beside the memo, since
    /// facts appear nowhere in the rendered document.
    pub notes_outside_extent: Vec<crate::scope::OutsideExtent>,
    /// Refusals recorded between one fact's mint and the previous one —
    /// what the author tried and could not do in the window that produced
    /// each fact. Human-owed and verbatim; a mint following a refusal is
    /// frequently correct. Like `notes_outside_extent`, only populated
    /// when a snapshot shipped beside the memo, and only as complete as
    /// the log inside it.
    pub mint_windows: Vec<crate::facts::MintWindow>,
    /// Working trees this memo's facts observed in more than one state,
    /// and the facts that saw each. A record rather than a warning — two
    /// facts seeing one repository in two states is the normal condition
    /// of any design that outlives an edit. What it settles is whether
    /// two facts asserting opposite things about the same code disagree
    /// about the world or about the same world, which before this the
    /// ledger could not answer at all. Same snapshot dependency as
    /// `mint_windows`.
    pub tree_states: Vec<crate::worldstate::RootStates>,
    /// Facts whose markers predate roots being recorded, so their tree
    /// state describes the process's working directory rather than what
    /// they read. Reported rather than passed over: an ungradable record
    /// is not a matching one.
    pub tree_ungradable: Vec<String>,
    /// True when the memo's ledger has no scope columns for any claim to
    /// declare into — a tetel-authored ledger. Reported once at document
    /// level rather than once per claim; see
    /// [`claims_without_declared_scope`] for why that changed.
    pub ledger_has_no_scope_columns: bool,
    /// One line per grounded claim describing how its evidence stands:
    /// witnessed (extent captured by this tool, in a named workspace) or
    /// ingested (extent typed by a caller). Human-owed, printed item by
    /// item, never a failure — see [`grounding_provenance`].
    pub grounding_provenance: Vec<String>,
    /// `(claim id, pass, note)` per record whose verdict is
    /// [`Verdict::Qualifies`]. Human-owed, never a failure.
    ///
    /// Until this existed, a qualifying verdict was invisible. On the
    /// first real independent grounding pass, the two claims the grounder
    /// declined to confirm — because the numbers they rest on could not
    /// be verified from what it was given — printed as plainly "grounded",
    /// while the one claim where it qualified a single premise of a
    /// multi-premise argument was the only thing reddening the report.
    /// The check fired on the wrong claim and was silent on the right
    /// ones.
    pub qualified_claims: Vec<(String, String, String)>,
    /// Claims **out of proof**: every record on file grades a wording this
    /// claim no longer carries, and nothing has graded the current one.
    /// The proof-house sense exactly — the stamp no longer certifies this
    /// barrel. A machine failure; see [`analyze_ledger`].
    ///
    /// The remedy is to **reprove**: ground the claim again against what it
    /// now says. Nothing else clears it, and nothing clears it silently —
    /// the ledger is append-only, so the superseding record is added rather
    /// than the stale one edited.
    pub out_of_proof: Vec<String>,
    /// Records that graded an earlier wording of a claim which *has* since
    /// been reproved. Human-owed history, never a failure — the claim is
    /// back in proof, and these are the marks from before it was. See
    /// [`analyze_ledger`] on why the distinction matters.
    pub superseded_evidence: Vec<String>,
}

impl Findings {
    pub fn machine_check_failed(&self) -> bool {
        !self.grammar_errors.is_empty()
            || !self.subset_failures.is_empty()
            || !self.abutting_failures.is_empty()
            || !self.unsettled_failures.is_empty()
            || !self.cascade_failures.is_empty()
            || !self.ledger_errors.is_empty()
            || !self.verdict_disagreements.is_empty()
            || !self.out_of_proof.is_empty()
            || self.provenance_failed()
    }

    /// Drift and an unreadable snapshot are machine failures: both are
    /// objective contradictions between a document and the record it
    /// claims to rest on, decidable without a human.
    ///
    /// A *missing* snapshot is deliberately not a failure. Every memo
    /// authored before `render --out` existed lacks one, and turning that
    /// into a hard failure would grade the tooling's own history rather
    /// than the document. It is reported as human-owed instead.
    pub fn provenance_failed(&self) -> bool {
        matches!(
            self.provenance,
            crate::snapshot::Provenance::Drifted { .. }
                | crate::snapshot::Provenance::Unreadable(_)
        )
    }
}

fn covers(extent: &[Designator], d: &Designator) -> bool {
    extent.iter().any(|e| match (e, d) {
| **claim** | a proposition resting on one or more facts |
| **grounding** | an independent pass grading claims from source alone, with the author's scope withheld |
| **out of proof** | a claim whose every record grades a wording it no longer carries. The stamp no longer certifies this barrel — a machine failure |
| **reprove** | ground a claim again against what it now says. The only thing that clears *out of proof*, and it adds a record rather than editing one |
| **superseded** | the marks from before a claim was reproved. History, human-owed, never a failure |
| **witnessed / ingested** | whether the tool captured the act itself, or only captured someone *reporting* the act |

Those three describe one state machine: revise a claim and it falls **out of proof**; **reprove** it
and the earlier records become **superseded**. The ledger is append-only, so nothing is ever cleared
by editing — only by adding a later proof.

## What `check` tells you

Two labelled partitions, each stating its own scope, and **never a single document-level verdict**:

- **machine-checked** — grammar, scope subset on enumerated rows, abutting literals, unsettled
  citations, dependency cascades, evidence-ledger import, verdict disagreement, claims out of proof,
  and provenance drift between a document and its own snapshot. These fail the run.
- **human-owed** — ungrounded claims, qualified verdicts in the grounder's own words, whether a claim
  was graded by the workspace that authored it or an independent one, notes reaching past their
  fact's extent, refusals recorded in a fact's mint window, and tetel's own standing non-coverage.
  **None of it is settled by a passing check**, and none of it fails the run.

Exit 2 means no tetel rows were found at all — out of scope, nothing checked, which is *not* a clean
run.

## Constraints — the things this must not become

- **No auto-bless.** A stored value that silently updates to match a fresh run turns *"the claim still
  holds"* into *"the command exited zero"*. Those are different propositions, and the second certifies
  drift with a green checkmark. A mismatch is always a loud failure a human resolves.
- **No green wall.** Mechanical green on the checkable claims leaks confidence onto a document whose
  worst defects are the uncheckable ones. Output partitions, and prints the human-owed list item by
  item. **The job is to concentrate human reading on the residue, not to shrink it.**
- **Never paraphrase.** If a tool returns a clause, it returns the clause's prose. The moment the
  server summarises, every downstream reader inherits the tool's reading of the document instead of
  the document — silently.
- **Prose is never generated from fields.** Facts may be captured and interpolated; arguments may not
  be assembled out of structure. A format that constrains what a design can express constrains what
  can be argued about it, and the strongest refutations on record came from readers engaging prose
  with full generality. Whoever writes it — person or agent — writes the argument themselves.
- **Refusals are format-level, never heuristic.** "You did not point at your evidence" is a decidable
  question. "This looks wrong" is not, and belongs in the human-owed partition or nowhere.

## Direction

Roughly in order, and each gated on measurement rather than enthusiasm — several proposed refusals
have already been built, measured against a real corpus, and **rejected on precision**:

- **Make the guards authoritative.** A commit hook runs the pair-guards locally today; CI would make
  them hold for a contributor who is not using the same setup.
- **More authoring-time refusals, where they are decidable.** Requiring a workspace-rooted search
  behind a claim that names a symbol; requiring a transplanted mechanism to carry its donor's stated
  premises; reporting prose revised since its claims were last grounded.
- **Supporting-span selection.** At mint time, point at the span of captured output that supports the
  assertion — refused unless it is a verbatim substring of a cited fact. The dual of the extent
  guarantee: the author cannot type an extent, and here could not invent support, only select it.
- **An obligation ledger.** Today a warning is a printed string with no lifecycle, so a warning that
  was ignored and one that was correctly resolved are indistinguishable in every artifact. Warnings
  raised, discharged with a *type*, and what is still owed reported by `check`.
- **Then, and only then, an optional model advisory pass** — a smaller model warning that a claim
//! # What this is not
//!
//! It is a **scope** check, never a truth check. Whether the note is
//! *correct* about the location it names is exactly the limit this
//! project registered as permanently out of reach ("insincere
//! examination" — capture makes the extent honest, not the
//! interpretation). Nothing here touches that.
//!
//! It is also **human-owed, never a refusal**. A note may legitimately
//! name a location as context, contrast, or a pointer to what to read
//! next, and only a person can tell that from an unsupported inference.
//! Refusing would make the honest case unwritable to catch the dishonest
//! one.
//!
//! # What it catches, measured, and what it does not
//!
//! Of the two overreaching facts in the memo that motivated it, this
//! catches **one**. F6 named a file and a line range (`graph_utils.rs
//! ~560-566`) it never opened, which is the strong tell and fires here.
//! F7's note asserted the client "mirrors the server's" walk while its
//! extent covered only the client — an overreach that names no location
//! at all, and so is invisible to any check of this shape.
//!
//! One refinement was tried and rejected on the evidence: flagging a
//! `module::symbol` reference whose module never appears in the fact's
//! own captured output. Measured against the same three facts, it would
//! have flagged a legitimate quotation (F3 citing `object_utils::
//! load_parcel`, a call site inside the code it did read) while missing
//! both real overreaches, because `graph_utils` and `merge_utils` do
//! appear in the read source as call sites. Naming a symbol the code you
//! read calls is normal; concluding about what that symbol *does* is the
//! failure — and those two are not distinguishable by string matching.
//!
//! So: a file-and-line reference to unopened code is caught, and a
//! conclusion drawn without naming anything is not. That is a real
//! ceiling, not a to-do.

//! `tetel claim` — assert, revise, or withdraw a proposition resting on
//! facts. Refuses without `--cites` (a claim must cite at least one
//! fact) and refuses on an unknown fact id. Before accepting a new
//! claim, prints an overlap report: existing facts, not among those
//! cited, that share an overlap key (see `pending.rs`'s doc comment on
//! fix 2) with the ones being cited — this is how the tool surfaces
//! evidence the author may have forgotten they already had.
//!
//! `--revise`/`--withdraw` are append-only, mirroring `tclaim`: both
//! refuse without `--why`, and a revision keeps the old proposition in
//! the log rather than overwriting it.

use std::collections::BTreeSet;
use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::facts;
use crate::workspace::{self, AuthoringError, Kind};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "event")]
pub enum ClaimEvent {
    Create {
        id: String,
        prop: String,
        from: Vec<String>,
        timestamp: u64,
    },
    Revise {
        id: String,
        #[serde(default)]
        prop: Option<String>,
        #[serde(default)]
        from: Option<Vec<String>>,
        why: String,
        timestamp: u64,
    },
    Withdraw {
        id: String,
        why: String,
        timestamp: u64,
    },
}

pub struct Claim {
    pub id: String,
    pub prop: String,
    pub from: Vec<String>,
    pub withdrawn: bool,
    pub revisions: usize,
}

fn log_path(workspace_dir: &Path) -> PathBuf {
    workspace_dir.join("claims.jsonl")
}

pub fn load_all(workspace_dir: &Path) -> io::Result<Vec<Claim>> {
    let events: Vec<ClaimEvent> = workspace::read_jsonl(&log_path(workspace_dir))?;
    let mut by_id: std::collections::BTreeMap<String, Claim> = std::collections::BTreeMap::new();
    let mut order: Vec<String> = Vec::new();
    for ev in events {
        match ev {
            ClaimEvent::Create { id, prop, from, .. } => {
                order.push(id.clone());
                by_id.insert(id.clone(), Claim { id, prop, from, withdrawn: false, revisions: 0 });
            }
            ClaimEvent::Revise { id, prop, from, .. } => {
                if let Some(c) = by_id.get_mut(&id) {
                    if let Some(p) = prop {
                        c.prop = p;
                    }
                    if let Some(f) = from {
                        c.from = f;
                    }
                    c.revisions += 1;
                }
            }
            ClaimEvent::Withdraw { id, .. } => {
                if let Some(c) = by_id.get_mut(&id) {
                    c.withdrawn = true;
                }
            }
        }
    }
    Ok(order.into_iter().filter_map(|id| by_id.remove(&id)).collect())
}

pub fn exists(workspace_dir: &Path, id: &str) -> io::Result<bool> {
    Ok(load_all(workspace_dir)?.iter().any(|c| c.id == id))
}

fn parse_ids(csv: &str) -> Vec<String> {
    csv.split(',').map(str::trim).filter(|s| !s.is_empty()).map(String::from).collect()
}

pub struct CreateOutcome {
    pub claim: Claim,
    /// `(fact id, current note)` for every non-cited fact sharing a
    /// designator with the cited ones.
    pub overlap: Vec<(String, String)>,
}

/// `tetel claim --proposition <text> --cites F1,F3`.
pub fn create(workspace_dir: &Path, prop: &str, from_csv: &str) -> Result<CreateOutcome, AuthoringError> {
    let ids = parse_ids(from_csv);
    if ids.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "claim",
            "a claim must rest on at least one fact (--cites was missing or empty); try `tetel query facts` to find one, or mint a new fact with `tetel look`/`tetel run` + `tetel fact`",
        ));
    }
    let mut missing = Vec::new();
    for id in &ids {
        if !facts::exists(workspace_dir, id)? {
            missing.push(id.clone());
        }
    }
    if !missing.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "claim",
            format!("cited fact(s) do not exist: {}; try `tetel query facts` to see what exists", missing.join(", ")),
        ));
    }
    if prop.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "claim", "no --proposition given; a claim needs a proposition"));
    }

    let overlap = overlap_report(workspace_dir, &ids)?;

    let id = workspace::next_id(workspace_dir, Kind::Claim)?;
    let event = ClaimEvent::Create { id: id.clone(), prop: prop.to_string(), from: ids.clone(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;

    Ok(CreateOutcome { claim: Claim { id, prop: prop.to_string(), from: ids, withdrawn: false, revisions: 0 }, overlap })
}

/// Every fact not among `cited_ids` that shares an extent key with the
/// union of `cited_ids`'s own extents (fix 2: the key is a resolved
/// path where a designator names a file, so three different line-ranges
/// of one file, and a plain read of it, all overlap each other now,
/// where the prototype's literal-command-string key never caught this).
fn overlap_report(workspace_dir: &Path, cited_ids: &[String]) -> io::Result<Vec<(String, String)>> {
    let all = facts::load_all(workspace_dir)?;
    let cited: BTreeSet<&str> = cited_ids.iter().map(String::as_str).collect();
    let mut union_keys: BTreeSet<&str> = BTreeSet::new();
    for f in &all {
        if cited.contains(f.id.as_str()) {
            for e in &f.extent {
                union_keys.insert(e.key.as_str());
            }
        }
    }
    let mut out = Vec::new();
    for f in &all {
        if cited.contains(f.id.as_str()) {
            continue;
        }
        if f.extent.iter().any(|e| union_keys.contains(e.key.as_str())) {
            out.push((f.id.clone(), f.note.clone()));
        }
    }
    Ok(out)
}

/// `tetel claim --revise <id> --why <text> [--proposition <text>] [--cites ...]`.
/// At least one of `new_prop`/`new_from_csv` must be given — a revision
/// that changes nothing isn't a revision.
pub fn revise(
    workspace_dir: &Path,
    id: &str,
    new_prop: Option<&str>,
    new_from_csv: Option<&str>,
    why: &str,
) -> Result<(), AuthoringError> {
    if !exists(workspace_dir, id)? {
        return Err(workspace::refuse(workspace_dir, "claim", format!("no such claim: {id}")));
    }
    if why.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "claim", "--revise requires --why (revisions must explain themselves)"));
    }
    let from = match new_from_csv {
        Some(csv) => {
            let ids = parse_ids(csv);
            let mut missing = Vec::new();
            for fid in &ids {
                if !facts::exists(workspace_dir, fid)? {
                    missing.push(fid.clone());
                }
            }
            if !missing.is_empty() {
                return Err(workspace::refuse(workspace_dir, "claim", format!("cited fact(s) do not exist: {}", missing.join(", "))));
            }
            Some(ids)
        }
        None => None,
    };
    let prop = new_prop.map(str::to_string);
    if prop.is_none() && from.is_none() {
        return Err(workspace::refuse(workspace_dir, "claim", "--revise requires a new --proposition and/or --cites"));
    }
    let event = ClaimEvent::Revise { id: id.to_string(), prop, from, why: why.to_string(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(())
}

/// `tetel claim --withdraw <id> --why <text>`.
pub fn withdraw(workspace_dir: &Path, id: &str, why: &str) -> Result<(), AuthoringError> {
    if !exists(workspace_dir, id)? {
        return Err(workspace::refuse(workspace_dir, "claim", format!("no such claim: {id}")));
    }
    if why.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "claim", "--withdraw requires --why"));
    }
    let event = ClaimEvent::Withdraw { id: id.to_string(), why: why.to_string(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(())
}

/// What `tetel claim` was asked to do — create, revise or withdraw. The
/// single shape both the CLI and the MCP server build and pass to
/// [`dispatch`], so the two front ends can never drift on which
/// combination of missing flags gets refused, or with what text.
pub enum ClaimRequest {
    Create { prop: Option<String>, from: Option<String> },
    Revise { id: String, prop: Option<String>, from: Option<String>, why: Option<String> },
    Withdraw { id: String, why: Option<String> },
}

pub enum ClaimOutcome {
    Created(CreateOutcome),
    Revised { id: String },
    Withdrawn { id: String },
}

/// Dispatches a [`ClaimRequest`] to [`create`], [`revise`] or
/// [`withdraw`], refusing with the exact text the CLI has always printed
/// for a flag a mode required but didn't get — lifted here (rather than
/// left as a bare `eprintln!` in `main.rs`) so the MCP server's
/// structured refusals carry the same guidance the CLI does, from the
/// one place that decides it.
pub fn dispatch(workspace_dir: &Path, req: ClaimRequest) -> Result<ClaimOutcome, AuthoringError> {
    match req {
        ClaimRequest::Withdraw { id, why } => {
            let why = why.ok_or_else(|| workspace::refuse(workspace_dir, "claim", "claim --withdraw requires --why"))?;
            withdraw(workspace_dir, &id, &why).map(|()| ClaimOutcome::Withdrawn { id })
        }
        ClaimRequest::Revise { id, prop, from, why } => {
            let why = why.ok_or_else(|| workspace::refuse(workspace_dir, "claim", "claim --revise requires --why"))?;
            revise(workspace_dir, &id, prop.as_deref(), from.as_deref(), &why).map(|()| ClaimOutcome::Revised { id })
        }
        ClaimRequest::Create { prop, from } => {
            let prop = prop.ok_or_else(|| workspace::refuse(workspace_dir, "claim", "claim requires --proposition"))?;
            let from = from.ok_or_else(|| workspace::refuse(workspace_dir, "claim", "claim requires --cites"))?;
            create(workspace_dir, &prop, &from).map(ClaimOutcome::Created)
        }
    }
}

//! `tetel prose` — compose the document's prose, one block at a time.
//! Creation is deliberately not gated (mirrors the prototype: prose is
//! where the author talks, not where they're audited — citing a
//! nonexistent claim isn't even checked here). Revision is gated the
//! same way `claims.rs`'s is: `--why` is required, and the superseded
//! text stays in the append-only log — `tetel render` only ever shows a
//! block's current text.
//!
//! # Document order, and why `--before` exists
//!
//! Insertion was dropped in this port on the grounds that none of the
//! four prototype runs ever used it — every block was composed and left
//! in append order. That reasoning had a selection effect in it, spotted
//! later by an agent writing with the tool: **those runs never needed
//! insertion because they wrote all their prose at the end**, which is
//! precisely the pattern the rhythm brief exists to prevent. The evidence
//! for removing the feature came from runs exhibiting the behaviour the
//! tool now tries to stop.
//!
//! Without insertion, document order is authoring order. An author
//! following the brief — writing a paragraph the moment a claim exists to
//! say something about — gets a document in discovery order, which reads
//! badly. The only way to get a well-ordered document is to defer prose
//! to the end. So the tool's shape rewarded the anti-pattern, and no
//! amount of brief text could outweigh that: a prompt asks, a shape
//! decides.
//!
//! `create` therefore takes an optional `before`, and document order is
//! the insertion order the log records rather than the order blocks were
//! appended. `tmove`-style reordering of existing blocks stays unported:
//! nothing has needed it, and unlike insertion its absence creates no
//! incentive to write badly.

use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::workspace::{self, AuthoringError, Kind};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "event")]
pub enum ProseEvent {
    Create {
        id: String,
        heading: bool,
        /// A markdown heading depth, 1..=6. `None` for a paragraph.
        /// Fix in this port: the prototype rendered every heading at one
        /// fixed depth (`##`), which two runs independently reported as
        /// a defect.
        #[serde(default)]
        level: Option<u8>,
        text: String,
        #[serde(default)]
        cite: Vec<String>,
        /// The block this one was inserted before, if any. Absent — the
        /// shape of every Create written before this field existed —
        /// means "append", so an old log replays exactly as it did.
        #[serde(default)]
        before: Option<String>,
        timestamp: u64,
    },
    Revise {
        id: String,
        text: String,
        why: String,
        /// Citations this revision sets, replacing whatever the block
        /// carried. Absent — the shape every revision written before this
        /// field existed has — leaves them untouched, so an old log
        /// replays exactly as it did.
        #[serde(default)]
        cite: Option<Vec<String>>,
        timestamp: u64,
    },
}

pub struct Block {
    pub id: String,
    pub heading: bool,
    pub level: Option<u8>,
    pub text: String,
    pub cite: Vec<String>,
    pub revisions: usize,
}

fn log_path(workspace_dir: &Path) -> PathBuf {
    workspace_dir.join("prose.jsonl")
}

/// Every block, in creation order — which is also document order, since
/// this port has no reordering (see the module doc comment).
pub fn load_all(workspace_dir: &Path) -> io::Result<Vec<Block>> {
    let events: Vec<ProseEvent> = workspace::read_jsonl(&log_path(workspace_dir))?;
    let mut by_id: std::collections::BTreeMap<String, Block> = std::collections::BTreeMap::new();
    let mut order: Vec<String> = Vec::new();
    for ev in events {
        match ev {
            ProseEvent::Create { id, heading, level, text, cite, before, .. } => {
                // Insert at the anchor if it is still present; otherwise
                // append. A dangling anchor cannot reorder silently — the
                // block lands at the end, where its absence is visible.
                match before.as_deref().and_then(|b| order.iter().position(|o| o == b)) {
                    Some(at) => order.insert(at, id.clone()),
                    None => order.push(id.clone()),
                }
                by_id.insert(id.clone(), Block { id, heading, level, text, cite, revisions: 0 });
            }
            ProseEvent::Revise { id, text, cite, .. } => {
                if let Some(b) = by_id.get_mut(&id) {
                    b.text = text;
                    // Absent means "unchanged", not "cleared": a
                    // revision written before this field existed must
                    // replay identically.
                    if let Some(c) = cite {
                        b.cite = c;
                    }
                    b.revisions += 1;
                }
            }
        }

//! # Language-agnostic by construction
//!
//! Tetel documents systems in any language, so nothing here may be tuned
//! to one. There is no list of languages and no list of extensions.
//!
//! What counts as a filename is decided in two stages. Shape rules reject
//! what cannot be a file — prose abbreviations, version numbers, the
//! tails of method chains. Then the token's extension must be one this
//! workspace has **actually opened**, read out of the captured extents.
//! A `look` at a Swift file is what teaches the scanner that `.swift`
//! names a file here; nobody enumerates that in advance and no language
//! is excluded in advance.
//!
//! The second stage is load-bearing, not belt-and-braces. Attribute
//! access — `self.value`, `response.data` — is filename-shaped under any
//! shape rule worth having: a good stem, a good extension. Only "was
//! this extension ever opened" separates it from a real file, and it does
//! so without knowing which language is being discussed.
//!
//! Its cost is that the vocabulary is per-extension, not per-language: a
//! workspace that has opened `mix.exs` has not thereby learned `.ex`. The
//! alternative is a hard-coded map from extension to language, which is
//! exactly the coupling this avoids. Pinned by a test rather than left to
//! be rediscovered.
